pub assume_specification<T, const N: usize>[ <[T]>::split_last_chunk::<N> ](
    slice: &[T],
) -> (ret: core::option::Option<(&[T], &[T; N])>)
    ensures
        match ret {
            core::option::Option::Some((init, last)) => {
                &&& slice@.len() >= N
                &&& init@ == slice@.subrange(0, slice@.len() as int - N as int)
                &&& last@ == slice@.subrange(slice@.len() as int - N as int, slice@.len() as int)
            },
            core::option::Option::None => N > slice@.len(),
        },
;

